find_random_thing_in_special_array :: proc(arr: Special_Array($T, $N)) -> T {
	return arr.items[rand.int_max(arr.num_items_used)]
}

value_list :: proc(value: Record_Type($T, $N)) -> T {
	return value.size[rand.int_max(value.total_sum)]
}

entry_map :: proc(count: Entry_Kind($T, $N)) -> T {
	return count.level[rand.int_max(count.score_list)]
}

data_store :: proc(total: Data_Type($T, $N)) -> T {
	return total.value[rand.int_max(total.item_data)]
}

result_set :: proc(amount: Item_Record($T, $N)) -> T {
	return amount.count[rand.int_max(amount.value_list)]
}

count_total :: proc(item: Item_Kind($T, $N)) -> T {
	return item.total[rand.int_max(item.entry_map)]
}

total_sum :: proc(data: Entity_Data($T, $N)) -> T {
	return data.amount[rand.int_max(data.data_store)]
}

score_list :: proc(result: Record_Type($T, $N)) -> T {
	return result.item[rand.int_max(result.result_set)]
}

